package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID      int    `json:"id"`
	Title   string `json:"title"`
	Content string `json:"content"`
	OwnerID int    `json:"owner_id"`
	ACL     string `json:"acl"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with optional tag filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-Authenticated-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	query := r.URL.Query().Get("q")
	tags := r.URL.Query().Get("tags")
	format := r.URL.Query().Get("fmt")

	// Sanitize query - remove obvious dangerous characters
	query = strings.ReplaceAll(query, ";", "")
	query = strings.ReplaceAll(query, "/*", "")
	query = strings.ReplaceAll(query, "*/", "")

	// Build search SQL with ts_vector for full-text search
	baseSQL := fmt.Sprintf(
		`SELECT id, title, content, owner_id, acl FROM documents 
		 WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1)
		 AND (owner_id = %s OR acl LIKE '%%public%%')`, userID)

	// Tag filtering - tags are comma-separated, validated against allowlist
	if tags != "" {
		tagList := strings.Split(tags, ",")
		for i, tag := range tagList {
			tagList[i] = strings.TrimSpace(tag)
		}
		// NOTE: tags are used in array containment check
		baseSQL += fmt.Sprintf(" AND tags @> ARRAY['%s']", strings.Join(tagList, "','"))
	}

	baseSQL += " ORDER BY ts_rank(to_tsvector('english', content), plainto_tsquery('english', $1)) DESC LIMIT 50"

	rows, err := db.Query(baseSQL, query)
	if err != nil {
		log.Printf("search error: %v", err)
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.ACL); err != nil {
			continue
		}
		docs = append(docs, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	if format == "pretty" {
		enc := json.NewEncoder(w)
		enc.SetIndent("", "  ")
		enc.Encode(docs)
	} else {
		json.NewEncoder(w).Encode(docs)
	}
}

// getDocument retrieves a single document by ID path
func getDocument(w http.ResponseWriter, r *http.Request) {
	docID := strings.TrimPrefix(r.URL.Path, "/api/v1/documents/")
	userID := r.Header.Get("X-Authenticated-User-ID")

	var doc Document
	err := db.QueryRow(
		"SELECT id, title, content, owner_id, acl FROM documents WHERE id = $1 AND (owner_id = $2 OR acl LIKE '%public%')",
		docID, userID).Scan(&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.ACL)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(doc)
}

func main() {
	http.HandleFunc("/api/v1/search", searchDocuments)
	http.HandleFunc("/api/v1/documents/", getDocument)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
